definition.script:
pipeline {
    agent any
    stages {
        stage('0. 说明：内联管道的 scm 变量') {
            steps {
                echo '本任务使用内联 Pipeline 脚本，scm 全局变量不可用；checkout scm 只适用于"从 SCM 读取流水线脚本"的任务（见 demo-03 多分支流水线）'
            }
        }
        stage('1. 显式 checkout + 高级克隆选项') {
            steps {
                script {
                    def scmVars = checkout([
                        $class: 'GitSCM',
                        branches: [[name: '*/test/test1']],
                        extensions: [
                            [$class: 'CloneOption', shallow: true, depth: 1, timeout: 10],
                            [$class: 'LocalBranch', localBranch: '**'],
                            [$class: 'CleanCheckout'],
                            [$class: 'SparseCheckoutPaths', sparseCheckoutPaths: [[path: 'scripts'], [path: 'src']]]
                        ],
                        userRemoteConfigs: [[url: 'https://github.com/yinshi197/JenkinsFile_repo.git']]
                    ])
                    echo "checkout 步骤返回的 Map：GIT_COMMIT = ${scmVars.GIT_COMMIT}"
                    echo "checkout 步骤返回的 Map：GIT_BRANCH = ${scmVars.GIT_BRANCH}"
                }
                sh '''
                    echo "[知识点] Pipeline 不会自动注入 GIT_* 环境变量（FreeStyle 才会）："
                    echo "  shell 里的 GIT_BRANCH = '$GIT_BRANCH'（为空是符合预期的）"
                    echo "[验证] 用 git 命令获取真实值："
                    git rev-parse HEAD
                    git branch --show-current
                    echo "--- 稀疏检出后的工作区（只有 scripts/ 和 src/）---"
                    ls -A
                '''
            }
        }
        stage('2. git 简写步骤') {
            steps {
                dir('shorthand-checkout') {
                    git url: 'https://github.com/yinshi197/JenkinsFile_repo.git', branch: 'main', changelog: false
                    sh 'git log -1 --oneline'
                }
            }
        }
        stage('3. 变更日志 changeSets') {
            steps {
                script {
                    def entries = 0
                    for (set in currentBuild.changeSets) {
                        entries += set.items.size()
                        for (item in set.items) {
                            echo "提交 " + item.commitId.take(8) + " | 作者: " + item.author + " | 说明: " + item.msg.trim()
                        }
                    }
                    echo "本次构建变更日志共 " + entries + " 条提交"
                }
            }
        }
        stage('4. 运行仓库中的脚本') {
            steps {
                sh '''
                    chmod +x scripts/*.sh
                    if [ -n "$(command -v python3)" ]; then
                        echo "检测到 python3，执行仓库脚本："
                        scripts/build.sh
                        scripts/test.sh
                    else
                        echo "[说明] Jenkins 容器里没有 python3，本阶段改为做 shell 语法校验："
                        bash -n scripts/build.sh
                        bash -n scripts/test.sh
                        echo "shell 语法检查通过"
                    fi
                '''
            }
        }
    }
    post {
        always {
            echo '流水线结束。提示：Pipeline 里读取 GIT_* 请用 checkout 的返回值或 git 命令，而不是直接引用 $GIT_BRANCH'
        }
    }
}
